public ExecutionResponse executeAllocation(String commandKey, String allocationKey, String executionKey,
                                           String volume, Long expectedVersion, String actor) {
    requireKey commandKey, executionKey, actor(X-Actor-Id);
    if (allocationKey == null || allocationKey.isBlank()) badRequest — path var always present, but validate key pattern? Path variable; use requireKey? Existing approve doesn't validate allocationKey beyond lookup. I'll just check non-blank.
    long vol = parsePositiveInteger("volume", volume);
    if (expectedVersion == null || expectedVersion < 0) badRequest;
    String params = "GATE_EXECUTE|" + allocationKey + "|" + executionKey + "|" + vol + "|" + expectedVersion + "|" + actor;
    return runCommand("GATE_EXECUTE", commandKey, params, ExecutionResponse.class, () -> {
        if (repository.findExecutionByKey(executionKey) != null) throw conflict EXECUTION_KEY_REUSED;
        AllocationRow allocation = repository.findAllocationByKey(allocationKey);
        if (allocation == null) throw notFound;
        lockWindowOf(allocation);
        allocation = repository.lockAllocationByKey(allocationKey);
        BasinRow basin = repository.findBasinByWindowId(allocation.windowId());
        if (basin == null) throw new ApiException(422, "GATE_NOT_ENABLED", "普通窗口不启用双池规则，不能执行");
        if (basin.version() != expectedVersion) throw conflict("VERSION_MISMATCH", ...);
        if (!STATUS_APPROVED.equals(allocation.status())) throw new ApiException(422, "ALLOCATION_NOT_APPROVED", ...);
        BigDecimal remaining = allocation.heldAmount().subtract(allocation.executedAmount());
        if (remaining.compareTo(BigDecimal.valueOf(vol)) < 0) throw quotaExceeded("累计执行将超过批准量，剩余可执行 " + fmt(remaining));
        // 执行前水位与界值校验
        checkBasinState(basin.upperVolumeM3(), basin, "执行前");
        long upperAfter = basin.upperVolumeM3() - vol;
        long lowerAfter = basin.lowerVolumeM3() + vol;
        // 执行后界值
        if (upperAfter < basin.upperMinM3() || upperAfter > basin.upperMaxM3()) throw 422 BASIN_BOUND_EXCEEDED 上池越界
        if (lowerAfter < basin.lowerMinM3() || lowerAfter > basin.lowerMaxM3()) throw 422 ...
        if (!levelDiffWithin(upperAfter, basin.upperAreaM2(), lowerAfter, basin.lowerAreaM2())) throw 422 WATER_LEVEL_EXCEEDED
        long now = nowNanos();
        repository.updateBasinVolumes(...);
        repository.incrementExecutedAmount(allocation.id(), BigDecimal.valueOf(vol), now);
        compute levels; insert execution; catch DuplicateKeyException → 409 EXECUTION_KEY_REUSED
        ExecutionRow row = repository.findExecutionByKey(executionKey);
        return toExecutionResponse(row, basin.version() + 1, remaining.subtract(BigDecimal.valueOf(vol)));
    });
}
